 static int checks;static void Check(bool pass,string name){if(!pass)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 sealed class Client:IDisposable {
  public TcpClient Tcp;public SslStream Ssl;public StreamReader R;public StreamWriter W;public string Id=Guid.NewGuid().ToString(),Token,Fp,Basis;public Dictionary<string,object> Hello;
  public Client(){Tcp=new TcpClient("127.0.0.1",Wire.Port);Tcp.ReceiveTimeout=2000;Tcp.SendTimeout=2000;Ssl=new SslStream(Tcp.GetStream(),false,(a,b,c,d)=>true);Ssl.AuthenticateAsClient("Velixa",null,SslProtocols.Tls12,false);R=new StreamReader(Ssl);W=new StreamWriter(Ssl,new UTF8Encoding(false)){AutoFlush=true};Hello=Read();Fp=Wire.Hash(Ssl.RemoteCertificate);}
  public void Send(object o){W.WriteLine(Wire.Json(o));}public Dictionary<string,object> Read(){return Wire.Parse(Wire.ReadLine(R));}
  public void Auth(string mode,string secret,string kind="Windows",bool wrong=false){string cn=Wire.RandomHex(32);Basis="Velixa-v2|"+Wire.S(Hello,"id")+"|"+Id+"|"+Fp+"|"+Wire.S(Hello,"nonce")+"|"+cn;Send(new{mode=mode,id=Id,name="Test device",kind=kind,sharing=1,cn=cn,w=1920,h=1080,proof=mode=="srp"?"":Wire.Mac(secret,Basis+"|client")});if(mode=="srp"){var m=Read();var g=Org.BouncyCastle.Tls.Crypto.Srp6StandardGroups.rfc5054_2048;var srp=new Srp6Client();srp.Init(g.N,g.G,new Sha256Digest(),new SecureRandom());var a=srp.GenerateClientCredentials(Convert.FromBase64String(Wire.S(m,"salt")),Encoding.UTF8.GetBytes(Basis),Encoding.UTF8.GetBytes(secret));srp.CalculateSecret(new Big(Wire.S(m,"b"),16));Send(new{a=a.ToString(16),m=srp.CalculateClientEvidenceMessage().ToString(16)});var evidence=Read();if(!srp.VerifyServerEvidenceMessage(new Big(Wire.S(evidence,"m"),16)))throw new Exception("Server proof");Send(new{proof=Wire.Mac(srp.CalculateSessionKey().ToString(16),Basis+"|confirm")});}var ready=Read();Token=mode=="resume"?secret:Wire.S(ready,"token");if(Wire.S(ready,"t")!="ready"||!Wire.Equal(Wire.S(ready,"proof"),Wire.Mac(Token,Basis+"|server")))throw new Exception("Ready proof");}
  public void Dispose(){Tcp.Close();}
 }
 static void Reject(Action a,string name){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,name);}
 [STAThread]static void Main(){try{Run();Console.WriteLine(checks+" checks passed");}catch(Exception e){Console.Error.WriteLine(e);Environment.ExitCode=1;}}
 static void Run(){using(var network=new Network()){network.Host();network.OpenPairing();string code=network.Code;Check(code.Length==4&&code.All(Char.IsDigit),"four digit code");Check((network.PairUntil-DateTime.UtcNow).TotalSeconds<=120,"two minute lifetime");
 using(var bad=new Client())Reject(()=>bad.Auth("srp",code=="0000"?"0001":"0000"),"wrong PIN rejected");
 string token,id;
 using(var good=new Client()){good.Auth("srp",code);token=good.Token;id=good.Id;Check(token.Length==64,"SRP creates strong per-device token");Check(network.PairUntil<DateTime.UtcNow,"successful pairing closes window");}
 using(var replay=new Client())Reject(()=>replay.Auth("srp",code),"closed PIN cannot pair another device");
 using(var resume=new Client()){resume.Id=id;resume.Auth("resume",token);Check(resume.Token==token,"trusted device reconnects with token");}
 using(var other=new Client())Reject(()=>other.Auth("resume",token),"token is bound to device identity");
 network.OpenPairing();string qr=network.QrToken;using(var android=new Client()){android.Auth("qr",qr,"Android");Check(android.Token.Length==64,"Android QR pairing");}
 using(var reuse=new Client())Reject(()=>reuse.Auth("qr",qr,"Android"),"QR token is single use");
 network.OpenPairing();network.PairUntil=DateTime.UtcNow.AddSeconds(-1);using(var expired=new Client())Reject(()=>expired.Auth("qr",network.QrToken,"Android"),"expired QR rejected");
 network.OpenPairing();code=network.Code;for(int i=0;i<5;i++)using(var c=new Client())try{c.Auth("srp",code=="0000"?"0001":"0000");}catch{}
 using(var exhausted=new Client())Reject(()=>exhausted.Auth("srp",code),"five attempts exhaust PIN window");
 network.OpenPairing();using(var c=new Client()){c.Auth("qr",network.QrToken,"Android");Thread.Sleep(6000);Check(!network.Snapshot().Any(p=>p.Id==c.Id),"offline peers expire after missed heartbeats");}
 }
 Check(!DeskSession.ValidEvent(Wire.Parse("{\"t\":\"move\",\"x\":\"NaN\",\"y\":0}")),"nonfinite pointer rejected");Check(!DeskSession.ValidEvent(Wire.Parse("{\"t\":\"enter\",\"x\":2,\"y\":0}")),"out of range pointer rejected");
 var rects=new List<RectangleF>{new RectangleF(0,0,220,124),new RectangleF(220,0,100,220),new RectangleF(0,-130,220,130),new RectangleF(0,124,220,124)};double ratio;
 Check(DeskGeometry.Find(rects,0,"right",.5,i=>true,out ratio)==1&&Math.Abs(ratio-62d/220)<.001,"right crossing preserves vertical position");Check(DeskGeometry.Find(rects,0,"top",.3,i=>true,out ratio)==2,"top crossing");Check(DeskGeometry.Find(rects,0,"bottom",.6,i=>true,out ratio)==3,"bottom crossing");Check(DeskGeometry.Find(rects,1,"left",.9,i=>i==0,out ratio)==-1,"nonoverlapping edge cannot switch");Check(DeskGeometry.Find(rects,0,"right",.5,i=>i!=1,out ratio)==-1,"offline screens are skipped");

 var split=new List<RectangleF>{new RectangleF(0,0,240,480)};for(int i=0;i<6;i++)split.Add(new RectangleF(240,i*80,120,80));for(int i=0;i<6;i++){Check(DeskGeometry.Find(split,0,"right",(i+.5)/6,j=>true,out ratio)==i+1&&Math.Abs(ratio-.5)<.001,"six-way split destination "+i);Check(DeskGeometry.Find(split,i+1,"left",.5,j=>true,out ratio)==0&&Math.Abs(ratio-(i+.5)/6)<.001,"six-way split return "+i);}
 Check(DeskGeometry.Find(split,0,"right",.5,j=>true,out ratio)==4,"shared endpoint belongs to one segment");Check(DeskGeometry.Find(split,0,"right",.25,j=>j!=2,out ratio)==-1,"sleeping segment is not crossed to another device");
 var rotated=split.Select(r=>new RectangleF(r.Y,r.X,r.Height,r.Width)).ToList();Check(DeskGeometry.Find(rotated,0,"bottom",.75,j=>true,out ratio)==5,"horizontal split segments");
 double lo,hi;Check(DeskGeometry.Segment(split[0],split[3],"right",out lo,out hi)&&Math.Abs(lo-2d/6)<.001&&Math.Abs(hi-.5)<.001,"lighting matches split detection");Check(Edge.SegmentBounds(new Rectangle(-1920,-100,1920,1200),"right",.25,.5)==new Rectangle(-6,200,6,300),"split overlay supports negative monitor coordinates");
 var gap=new List<RectangleF>{new RectangleF(0,0,100,100),new RectangleF(110,0,100,100)};Check(DeskGeometry.Find(gap,0,"right",.5,j=>true,out ratio)==-1,"empty gap cannot switch");
 var random=new Random(42);var packed=new List<RectangleF>();for(int i=0;i<80;i++){var r=new RectangleF(random.Next(-500,500),random.Next(-500,500),random.Next(40,240),random.Next(40,240));r.Location=DeskGeometry.Snap(r,packed);Check(!packed.Any(b=>DeskGeometry.Overlaps(r,b)),"snap collision case "+i);if(packed.Count>0)Check(packed.Any(b=>new[]{"left","right","top","bottom"}.Any(side=>DeskGeometry.Segment(r,b,side,out lo,out hi))),"snap has reachable edge "+i);packed.Add(r);}

 using(var network=new Network()){network.IsHost=true;using(var desk=new DeskSession(network,new Receiver(),a=>a())){desk.Host();desk.Input.Enabled=false;var events=new List<Dictionary<string,object>>();var first=new Peer{Id=Guid.NewGuid().ToString(),Name="Laptop",Kind="Windows",SendAction=o=>events.Add(Wire.Parse(Wire.Json(o)))};var target=new Peer{Id=Guid.NewGuid().ToString(),Name="Phone",Kind="Android",SendAction=o=>events.Add(Wire.Parse(Wire.Json(o)))};network.Peers.Add(first);network.Peers.Add(target);network.Joined(first);network.Joined(target);desk.SelectSource(first.Id);long epoch=desk.Epoch;events.Clear();network.Packet(first,Wire.Parse(Wire.Json(new{t="route",id=target.Id,epoch=epoch,@event=new{t="move",x=.5,y=.5}})));Check(events.Count==1&&Wire.S(events[0],"t")=="move","selected Windows source routes to Android");events.Clear();network.Packet(target,Wire.Parse(Wire.Json(new{t="route",id=first.Id,epoch=epoch,@event=new{t="move",x=.5,y=.5}})));Check(events.Count==0,"Android cannot send input");desk.SelectSource(Network.LocalId);desk.Input.Enabled=false;events.Clear();network.Packet(first,Wire.Parse(Wire.Json(new{t="route",id=target.Id,epoch=epoch,@event=new{t="key",vk=65,down=true}})));Check(events.Count==0,"revoked source and stale epoch rejected");desk.Position(target.Id,120,-200);Check(!desk.Devices.Any(a=>desk.Devices.Any(b=>a!=b&&DeskGeometry.Overlaps(a.Bounds,b.Bounds))),"two dimensional layout snaps without overlap");desk.SleepDevice(target.Id,true);Check(desk.Devices.Find(d=>d.id==target.Id).sleeping&&!desk.Input.Order.Find(p=>p!=null&&p.Id==target.Id).Online,"manual sleep removes input target");desk.SelectSource(first.Id);events.Clear();network.Packet(first,Wire.Parse(Wire.Json(new{t="route",id=target.Id,epoch=desk.Epoch,@event=new{t="move",x=.5,y=.5}})));Check(events.Count==0,"coordinator blocks input to sleeping target");network.Joined(target);Check(desk.Devices.Find(d=>d.id==target.Id).sleeping,"reconnection does not clear manual sleep");desk.SleepDevice(target.Id,false);Check(desk.Devices.Find(d=>d.id==target.Id).Available,"wake restores without pairing");desk.SetAwake(target.Id,false);Check(!desk.Devices.Find(d=>d.id==target.Id).Available,"automatic sleep excludes device");desk.SetAwake(target.Id,true);desk.ResizeDevice(target.Id,.4);Check(Math.Abs(desk.Input.Order.Find(p=>p!=null&&p.Id==target.Id).Scale-.4)<.001,"custom size reaches input geometry");string home=desk.Store.active;desk.Profile("create","Studio");string studio=desk.Store.active;desk.ResizeDevice(target.Id,1.5);desk.SleepDevice(target.Id,true);desk.Profile("switch",home);Check(desk.DeskName=="My desk"&&!desk.Devices.Find(d=>d.id==target.Id).sleeping&&Math.Abs(desk.Devices.Find(d=>d.id==target.Id).scale-.4)<.001,"desks keep independent sleep and sizes");desk.Profile("switch",studio);Check(desk.DeskName=="Studio"&&desk.Devices.Find(d=>d.id==target.Id).sleeping,"desk switch restores saved configuration");desk.Profile("rename","Office");Check(desk.DeskName=="Office","desk rename");desk.SleepDevice(first.Id,true);Check(desk.Source!=first.Id,"sleeping input source safely revoked");desk.ResizeDevice(target.Id,Double.NaN);Check(desk.Devices.Find(d=>d.id==target.Id).scale==1.5,"nonfinite scale rejected");var saved=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<DeskStore>(Wire.LoadSecret("desks-v3.bin",""));Check(saved.desks.Count==2&&saved.active==studio,"profiles persisted across restart");desk.Profile("delete","");Check(desk.Store.desks.Count==1&&desk.Store.active==home,"delete switches safely to retained desk");network.Peers.Remove(first);network.Left(first);Check(desk.Devices.Any(d=>d.id==first.Id&&!d.online),"offline device remains on desk");desk.Input.Enabled=false;}}
 using(var network=new Network()){network.IsHost=true;var pending=new List<Action>();using(var desk=new DeskSession(network,new Receiver(),a=>pending.Add(a))){desk.Host();desk.Input.Enabled=false;var peer=new Peer{Id=Guid.NewGuid().ToString(),Name="Other PC",Kind="Windows",SendAction=o=>{}};network.Peers.Add(peer);network.Joined(peer);foreach(var a in pending.ToArray())a();pending.Clear();Check(desk.Automatic,"automatic input is the default");desk.SelectSource(peer.Id);desk.Input.PhysicalActivity();Check(desk.Source==peer.Id&&pending.Count==1,"physical input schedules takeover outside the hook");desk.Input.PhysicalActivity();Check(pending.Count==1,"physical input requests are coalesced");foreach(var a in pending.ToArray())a();pending.Clear();Check(desk.Source==Network.LocalId,"physical input takes over without a prompt");desk.UseSource(peer.Id);Check(!desk.Automatic&&desk.Source==peer.Id,"manual source disables automatic takeover");desk.Input.PhysicalActivity();Check(pending.Count==0,"fixed source ignores other local input for sharing");network.Packet(peer,Wire.Parse(Wire.Json(new{t="source",id=Network.LocalId})));foreach(var a in pending.ToArray())a();pending.Clear();Check(desk.Source==peer.Id,"fixed source cannot be overridden by activity requests");var saved=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<DeskStore>(Wire.LoadSecret("desks-v3.bin",""));Check(!saved.automatic,"manual mode persists");desk.SetAutomatic(true);Check(desk.Automatic,"automatic mode can be selected again");desk.SelectSource(Network.LocalId);network.Packet(peer,Wire.Parse(Wire.Json(new{t="source",id=peer.Id})));foreach(var a in pending.ToArray())a();pending.Clear();Check(desk.Source==peer.Id,"other Windows PC can claim automatic source");desk.Input.Enabled=false;}}

 using(var network=new Network()){network.IsHost=true;using(var desk=new DeskSession(network,new Receiver(),a=>a())){desk.Preview=true;desk.Host();desk.Input.Enabled=false;var messages=new List<Dictionary<string,object>>();var a=new Peer{Id=Guid.NewGuid().ToString(),Name="A",Kind="Windows",Sharing=true,SendAction=o=>{}};var b=new Peer{Id=Guid.NewGuid().ToString(),Name="B",Kind="Windows",Sharing=true,SendAction=o=>messages.Add(Wire.Parse(Wire.Json(o)))};network.Peers.Add(a);network.Peers.Add(b);network.Joined(a);network.Joined(b);messages.Clear();network.Packet(a,Wire.Parse(Wire.Json(new{t="share",to=b.Id,from="spoof",body=new{kind="begin",id=Guid.NewGuid().ToString("N"),name="document.txt",size=5,format="file"}})));Check(messages.Count==1&&Wire.S(messages[0],"from")==a.Id,"sharing relay binds sender to authenticated peer");desk.SleepDevice(b.Id,true);messages.Clear();network.Packet(a,Wire.Parse(Wire.Json(new{t="share",to=b.Id,body=new{kind="mic-begin"}})));Check(messages.Count==0,"sleeping devices cannot receive shared data");desk.SleepDevice(b.Id,false);messages.Clear();a.Sharing=false;network.Packet(a,Wire.Parse(Wire.Json(new{t="share",to=b.Id,body=new{kind="begin"}})));Check(messages.Count==0,"old clients cannot originate sharing packets");a.Sharing=true;string origin=null;desk.Shared=(from,body)=>origin=from;network.Packet(a,Wire.Parse(Wire.Json(new{t="share",to=Network.LocalId,body=new{kind="ack"}})));Check(origin==a.Id,"coordinator can receive sharing data");desk.Input.Enabled=false;}}

